#include <stdio.h>

#define N 8

static void printArr(const char *tag, const int a[], int n)
{
    int i;
    printf("%s", tag);
    for (i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
}

/* 直接插入排序（稳定） */
static void insertSort(int a[], int n)
{
    int i, j;
    for (i = 1; i < n; i++) {
        if (a[i] < a[i - 1]) {
            int t = a[i];
            for (j = i - 1; j >= 0 && a[j] > t; j--)
                a[j + 1] = a[j];
            a[j + 1] = t;
        }
        printArr("insert pass: ", a, n);
    }
}

/* 冒泡排序（稳定，带提前结束标志） */
static void bubbleSort(int a[], int n)
{
    int i, j, exchanged;
    for (i = 0; i < n - 1; i++) {
        exchanged = 0;
        for (j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) {         /* 严格大于才交换 → 稳定 */
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                exchanged = 1;
            }
        printArr("bubble pass: ", a, n);
        if (!exchanged) break;
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int b[N];
    int i;

    for (i = 0; i < N; i++) b[i] = a[i];
    insertSort(a, N);
    bubbleSort(b, N);
    return 0;
}

#include <stdio.h>

#define N 8

/* 简单选择排序（不稳定），*swaps 统计交换次数 */
static void selectSort(int a[], int n, int *swaps)
{
    int i, j, k;
    *swaps = 0;
    for (i = 0; i < n - 1; i++) {
        k = i;
        for (j = i + 1; j < n; j++)
            if (a[j] < a[k]) k = j;
        if (k != i) {
            int t = a[i]; a[i] = a[k]; a[k] = t;
            (*swaps)++;
        }
        printf("pass %d: ", i + 1);
        for (j = 0; j < n; j++) printf("%d ", a[j]);
        printf("\n");
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int swaps = 0;

    selectSort(a, N, &swaps);
    printf("swaps=%d\n", swaps);
    return 0;
}

#include <stdio.h>

#define N 8

/* 直接插入排序：a[0] 作哨兵兼暂存，数据在 a[1..n] */
static void insertSort(int a[], int n)
{
    int i, j;
    for (i = 2; i <= n; i++) {
        if (a[i] < a[i - 1]) {
            a[0] = a[i];                 /* 暂存待插值 */
            for (j = i - 1; a[0] < a[j]; j--)
                a[j + 1] = a[j];         /* 后移 */
            a[j + 1] = a[0];             /* 插入到位 */
        }
        printf("pass %d: ", i - 1);
        for (j = 1; j <= n; j++) printf("%d ", a[j]);
        printf("\n");
    }
}

int main(void)
{
    int a[N + 1] = {0, 49, 38, 65, 97, 76, 13, 27, 49};

    insertSort(a, N);
    return 0;
}

#include <stdio.h>

#define N 8

/* 折半插入排序：折半找插入位置，再统一后移 */
static void binInsertSort(int a[], int n)
{
    int i, j, low, high, mid, t;
    for (i = 1; i < n; i++) {
        t = a[i];
        low = 0; high = i - 1;
        while (low <= high) {
            mid = (low + high) / 2;
            if (a[mid] > t) high = mid - 1;
            else            low  = mid + 1;
        }
        for (j = i - 1; j >= low; j--)
            a[j + 1] = a[j];
        a[low] = t;
    }
}

/* 希尔排序的一趟：对间隔 gap 的子序列做直接插入 */
static void shellPass(int a[], int n, int gap)
{
    int i, j;
    for (i = gap; i < n; i++) {
        if (a[i] < a[i - gap]) {
            int t = a[i];
            for (j = i - gap; j >= 0 && a[j] > t; j -= gap)
                a[j + gap] = a[j];
            a[j + gap] = t;
        }
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int b[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int gaps[3] = {4, 2, 1};
    int g, i;

    binInsertSort(a, N);
    printf("binInsert: ");
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");

    for (g = 0; g < 3; g++) {
        shellPass(b, N, gaps[g]);
        printf("gap=%d: ", gaps[g]);
        for (i = 0; i < N; i++) printf("%d ", b[i]);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

#define N 8

/* 一趟划分：以 a[low] 为枢轴，返回枢轴最终位置 */
static int partition(int a[], int low, int high)
{
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot) high--;
        a[low] = a[high];
        while (low < high && a[low] <= pivot) low++;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}

static void quickSort(int a[], int low, int high)
{
    if (low < high) {
        int p = partition(a, low, high);
        quickSort(a, low, p - 1);
        quickSort(a, p + 1, high);
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int i;
    quickSort(a, 0, N - 1);
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 8

/* 自顶向下调整：使 a[s..m] 成为大根堆 */
static void heapAdjust(int a[], int s, int m)
{
    int j, t = a[s];
    for (j = 2 * s; j <= m; j *= 2) {
        if (j < m && a[j] < a[j + 1]) j++;   /* 取较大孩子 */
        if (t >= a[j]) break;                /* 已到位 */
        a[s] = a[j]; s = j;                  /* 继续下沉 */
    }
    a[s] = t;
}

/* 堆排序：a[1..n] 存数据 */
static void heapSort(int a[], int n)
{
    int i, t;
    for (i = n / 2; i >= 1; i--) heapAdjust(a, i, n);   /* 建初始堆 */
    for (i = n; i > 1; i--) {
        t = a[1]; a[1] = a[i]; a[i] = t;                /* 堆顶与末尾交换 */
        heapAdjust(a, 1, i - 1);                        /* 调整剩余 */
    }
}

int main(void)
{
    int a[N + 1] = {0, 49, 38, 65, 97, 76, 13, 27, 49};
    int i;
    heapSort(a, N);
    for (i = 1; i <= N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 8

/* 归并 [low..mid] 与 [mid+1..high] 两段有序序列到 tmp 再回写 */
static void merge(int a[], int tmp[], int low, int mid, int high)
{
    int i = low, j = mid + 1, k = low;
    while (i <= mid && j <= high) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];   /* <= 保证稳定 */
        else              tmp[k++] = a[j++];
    }
    while (i <= mid)  tmp[k++] = a[i++];
    while (j <= high) tmp[k++] = a[j++];
    for (k = low; k <= high; k++) a[k] = tmp[k];
}

static void mergeSort(int a[], int tmp[], int low, int high)
{
    if (low < high) {
        int mid = (low + high) / 2;
        mergeSort(a, tmp, low, mid);
        mergeSort(a, tmp, mid + 1, high);
        merge(a, tmp, low, mid, high);
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int tmp[N];
    int i;
    mergeSort(a, tmp, 0, N - 1);
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 8

/* LSD 一趟：按 exp（1=个位,10=十位）做稳定的计数分配—收集 */
static void radixPass(int a[], int tmp[], int n, int exp)
{
    int count[10] = {0};
    int i, d;
    for (i = 0; i < n; i++) count[(a[i] / exp) % 10]++;
    for (i = 1; i < 10; i++) count[i] += count[i - 1];   /* 累积定位 */
    for (i = n - 1; i >= 0; i--) {                        /* 倒序保持稳定 */
        d = (a[i] / exp) % 10;
        tmp[--count[d]] = a[i];
    }
    for (i = 0; i < n; i++) a[i] = tmp[i];
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int tmp[N];
    int i;
    radixPass(a, tmp, N, 1);    /* 第一趟：个位 */
    printf("ones : ");
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    radixPass(a, tmp, N, 10);   /* 第二趟：十位 */
    printf("tens : ");
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
